package api.publica;
import static org.junit.jupiter.api.Assertions.*;import java.lang.reflect.RecordComponent;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.stream.*;import org.junit.jupiter.api.Test;import negocio.PosicionJugador;
class ConsultaConvocatoriasComunidadServiceTest {
 @Test void validaFiltrosYPaginacion(){assertDoesNotThrow(()->ConsultaConvocatoriasComunidadService.validarPaginacion(1,12));assertThrows(IllegalArgumentException.class,()->ConsultaConvocatoriasComunidadService.validarPaginacion(0,12));assertEquals(LocalDate.of(2026,10,21),ConsultaConvocatoriasComunidadService.fecha("2026-10-21"));assertEquals(1,ConsultaConvocatoriasComunidadService.lugares("1"));assertEquals(PosicionJugador.REVES,ConsultaConvocatoriasComunidadService.posicion("reves"));assertThrows(IllegalArgumentException.class,()->ConsultaConvocatoriasComunidadService.lugares("4"));}
 @Test void consultaSoloPublicaActivasFuturasYReservasVigentes(){String q=ConsultaConvocatoriasComunidadService.base();assertTrue(q.contains("cv.estado IN ('ABIERTA','EN_COORDINACION')"));assertTrue(q.contains("cv.clave_activa=1"));assertTrue(q.contains("cv.fecha_expiracion>?"));assertTrue(q.contains("r.estado IN ('PENDIENTE','CONFIRMADA')"));var c=ConsultaConvocatoriasComunidadService.construir(ConsultaConvocatoriasComunidadService.Filtros.vacios(),LocalDateTime.now());assertTrue(c.sql().contains("TIMESTAMP(r.fecha,r.hora_inicio)>?"));}
 @Test void dtoPublicoNoExponeDatosSensibles(){Set<String> campos=Arrays.stream(ConvocatoriaPublicaDTO.Turno.class.getRecordComponents()).map(RecordComponent::getName).collect(Collectors.toSet());assertTrue(campos.containsAll(Set.of("fecha","horaInicio","horaFin","cancha","resumenCupo","convocante")));for(String privado:List.of("telefono","email","documento","precio","pagos","observacionesAdministrativas","clienteId"))assertFalse(campos.contains(privado));}
 @Test void fuenteNoConsultaColumnasPrivadas()throws Exception{String codigo=Files.readString(Path.of("src/main/java/api/publica/ConsultaConvocatoriasComunidadService.java"));for(String privado:List.of("telefono","email","documento","precio_total","observaciones_administrativas","cliente_ocasional"))assertFalse(codigo.contains(privado));assertTrue(codigo.contains("ORDER BY r.fecha,r.hora_inicio,cv.id"));assertTrue(codigo.contains("LIMIT ? OFFSET ?"));}
}
